using System;using System.Drawing;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class CalculationProfileForm:Form {
Project project;TextBox standard,edition,source,assumptions;public bool Changed{get;private set;}
public CalculationProfileForm(Project p){project=p;Text="Método, edição e hipóteses do projeto";Size=new Size(1050,740);MinimumSize=new Size(850,650);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var panel=new TableLayoutPanel{Dock=DockStyle.Top,Height=300,ColumnCount=2,RowCount=4,Padding=new Padding(12)};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,170));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));var existing=p.CalculationProfile??new CalculationProfile();standard=Field(panel,0,"Referência normativa",existing.Standard,false);edition=Field(panel,1,"Edição / ano / revisão",existing.Edition,false);source=Field(panel,2,"Fonte da referência",existing.ReferenceSource,false);assumptions=Field(panel,3,"Hipóteses do projeto",existing.Assumptions,true);panel.RowStyles.Add(new RowStyle(SizeType.Absolute,40));panel.RowStyles.Add(new RowStyle(SizeType.Absolute,40));panel.RowStyles.Add(new RowStyle(SizeType.Absolute,40));panel.RowStyles.Add(new RowStyle(SizeType.Percent,100));var preview=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White,Text=CalculationManifest.Describe(p)};var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50,FlowDirection=FlowDirection.RightToLeft};var save=new Button{Text="Registrar perfil",AutoSize=true};save.Click+=delegate{try{ApplyFields();DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Método",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};buttons.Controls.Add(save);var cancel=new Button{Text="Cancelar",AutoSize=true,DialogResult=DialogResult.Cancel};buttons.Controls.Add(cancel);var notice=new Label{Dock=DockStyle.Top,Height=70,Padding=new Padding(12),Text="Motor ativo: "+CalculationManifest.EngineId+".\r\nA referência e a edição são declarações do projetista; esses textos não mudam o algoritmo. Registrar vincula esta revisão do motor ao projeto. Não declara conformidade normativa."};Controls.Add(preview);Controls.Add(buttons);Controls.Add(panel);Controls.Add(notice);CancelButton=cancel;Shown+=delegate{preview.SelectionStart=0;preview.SelectionLength=0;preview.ScrollToCaret();standard.Focus();};}
static TextBox Field(TableLayoutPanel panel,int row,string label,string text,bool multiline){panel.Controls.Add(new Label{Text=label,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,row);var box=new TextBox{Dock=DockStyle.Fill,Text=text,MaxLength=10000,Multiline=multiline,ScrollBars=multiline?ScrollBars.Vertical:ScrollBars.None};panel.Controls.Add(box,1,row);return box;}
void ApplyFields(){CalculationManifest.Apply(project,new CalculationProfile{Standard=standard.Text,Edition=edition.Text,ReferenceSource=source.Text,Assumptions=assumptions.Text});Changed=true;}
}
partial class Studio{void ConfigureCalculationProfile(){using(var form=new CalculationProfileForm(project))if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
}
